import{_ as a,o as i,c as t,a8 as s}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"6.0.x","description":"","frontmatter":{"title":"6.0.x","lang":"en"},"headers":[],"relativePath":"changes/6_0_x.md","filePath":"changes/6_0_x.md","lastUpdated":1790354326000}'),l={name:"changes/6_0_x.md"};function n(o,e,r,d,h,c){return i(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjI2LjAueCUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzU0MzI2MDAwJTdE"},[...e[0]||(e[0]=[s(`<h1 id="change-log-6-0-x" tabindex="-1">Change Log (6.0.x) <a class="header-anchor" href="#change-log-6-0-x" aria-label="Permalink to &quot;Change Log (6.0.x)&quot;">​</a></h1><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><div class="tip custom-block"><p class="custom-block-title">What is a breaking change?</p><ul><li>The original configuration file may not work, for example, if a directive item is removed or renamed.</li><li>It may be necessary to update the build environment, such as installing new dependencies.</li></ul></div><h2 id="_6-0-3-2021-08-02-utc-0800" tabindex="-1">[6.0.3] - 2021-08-02 UTC+0800 <a class="header-anchor" href="#_6-0-3-2021-08-02-utc-0800" aria-label="Permalink to &quot;[6.0.3] - 2021-08-02 UTC+0800&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A segmentation fault may be raised when releasing resources from the virtual machine.</li></ul><hr><h2 id="_6-0-2-2021-08-01-utc-0800" tabindex="-1">[6.0.2] - 2021-08-01 UTC+0800 <a class="header-anchor" href="#_6-0-2-2021-08-01-utc-0800" aria-label="Permalink to &quot;[6.0.2] - 2021-08-01 UTC+0800&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The whitelist of URL and Referer in the upper-level configuration cannot be inherited properly.</li></ul><hr><h2 id="_6-0-1-2021-07-30-utc-0800" tabindex="-1">[6.0.1] - 2021-07-30 UTC+0800 <a class="header-anchor" href="#_6-0-1-2021-07-30-utc-0800" aria-label="Permalink to &quot;[6.0.1] - 2021-07-30 UTC+0800&quot;">​</a></h2><h3 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to &quot;Deprecated&quot;">​</a></h3><ul><li>Deprecates the parameters <code>interval</code> and <code>percent</code> of the directive <code>waf_cache</code>, but does not remove them, only that they no longer have any effect. These two parameters will be removed in the future.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Improved performance of CC protection.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Extreme cases may waste a lot of memory. Thanks to <a href="https://github.com/RekGRpth" target="_blank" rel="noreferrer">@RekGRpth</a> for their help.</li></ul><hr><h2 id="_6-0-0-2021-07-21-utc-0800" tabindex="-1">[6.0.0] - 2021-07-21 UTC+0800 <a class="header-anchor" href="#_6-0-0-2021-07-21-utc-0800" aria-label="Permalink to &quot;[6.0.0] - 2021-07-21 UTC+0800&quot;">​</a></h2><h3 id="note" tabindex="-1">NOTE <a class="header-anchor" href="#note" aria-label="Permalink to &quot;NOTE&quot;">​</a></h3><ul><li><p><strong>This release contains some breaking changes.</strong></p></li><li><p>Advanced rules have a high performance cost because the principle is to compile the rules into a series of instructions that are then executed by the VM.</p></li></ul><h3 id="upgrade-from-5-x-x-to-6-x-x" tabindex="-1">Upgrade from 5.x.x to 6.x.x <a class="header-anchor" href="#upgrade-from-5-x-x-to-6-x-x" aria-label="Permalink to &quot;Upgrade from 5.x.x to 6.x.x&quot;">​</a></h3><ol><li><p>Create a new empty file named <code>advanced</code> in the rules directory.</p></li><li><p>If the directive <code>waf_priority</code> is used, you can delete it or modify it according to the directive in the documentation.</p></li></ol><h3 id="pre-built-modules" tabindex="-1">Pre-built modules <a class="header-anchor" href="#pre-built-modules" aria-label="Permalink to &quot;Pre-built modules&quot;">​</a></h3><p>We now provide pre-compiled modules that can be used as long as the following requirements are met.</p><ol><li>The version of nginx must be the latest stable or mainline version.</li><li>The C standard library implementation must be the GNU implementation or the MUSL implementation.</li></ol><blockquote><p>The download script will automatically check if the second condition is met.</p></blockquote><p>You can execute <code>assets/download.sh</code> to download the corresponding version of the module and save it to the current directory. Here is the use case.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nginx-stable ngx_waf-stable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nginx-mainline ngx_waf-stable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mainline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nginx-stable ngx_waf-beta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beta</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nginx-mainline ngx_waf-beta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/download</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mainline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beta</span></span></code></pre></div><blockquote><p>Each update takes about an hour and a half to compile the module, so it is recommended that you download the updated module more than two hours after the update, otherwise you may download the old module.</p></blockquote><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Advanced rules are supported, see the documentation for details.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Remove mode <code>COMPAT</code>, no longer fully compatible with <code>ngx_http_rewrite_module</code>.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p>Updated the directive <code>waf_priority</code>, see the documentation for details.</p></li><li><p>You can now use all the directives of this module in blocks <code>http</code>, <code>server</code> and <code>location</code></p></li></ul>`,37)])])}const m=a(l,[["render",n]]);export{u as __pageData,m as default};
